create extension if not exists pgcrypto;

create type public.profile_role as enum ('user','admin');
create type public.profile_status as enum ('active','suspended','banned','deactivated');
create type public.fixture_status as enum ('scheduled','live','finished','postponed','void');
create type public.prize_status as enum ('open','paid');
create type public.ledger_type as enum ('prize','offer','referral_general','referral_promo','spin','bonus','withdrawal','refund','adjustment');
create type public.ledger_status as enum ('pending','available','reversed');

create table public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 nickname text not null unique check (length(nickname) between 3 and 24),
 phone text unique,
 email text,
 phone_verified boolean not null default false,
 email_verified boolean not null default false,
 role public.profile_role not null default 'user',
 status public.profile_status not null default 'active',
 deactivated_at timestamptz,
 referral_code text not null unique,
 referred_by uuid references public.profiles(id),
 referred_program text check (referred_program in ('general','promo')),
 promo_campaign_id uuid,
 streak_count integer not null default 0 check (streak_count >= 0),
 last_visit_date date,
 boosters_bonus integer not null default 0 check (boosters_bonus >= 0),
 nickname_changed_at timestamptz,
 created_at timestamptz not null default now()
);
create table public.competitions (id uuid primary key default gen_random_uuid(), name text not null, country text, external_id text unique, created_at timestamptz not null default now());
create table public.teams (id uuid primary key default gen_random_uuid(), competition_id uuid references public.competitions(id) on delete set null, name text not null, external_id text unique, created_at timestamptz not null default now());
create table public.gameweeks (id uuid primary key default gen_random_uuid(), starts_at timestamptz not null, ends_at timestamptz not null, prize_status public.prize_status not null default 'open', qualification_waived boolean not null default false, check (ends_at > starts_at));
create table public.fixtures (id uuid primary key default gen_random_uuid(), competition_id uuid references public.competitions(id) on delete set null, home_team_id uuid references public.teams(id), away_team_id uuid references public.teams(id), kickoff_at timestamptz not null, status public.fixture_status not null default 'scheduled', home_goals integer check (home_goals is null or home_goals >= 0), away_goals integer check (away_goals is null or away_goals >= 0), settled_at timestamptz, external_id text unique, created_at timestamptz not null default now());
create table public.predictions (user_id uuid not null references public.profiles(id) on delete cascade, fixture_id uuid not null references public.fixtures(id) on delete cascade, outcome text not null check (outcome in ('home','draw','away')), home_goals integer not null check (home_goals >= 0), away_goals integer not null check (away_goals >= 0), booster boolean not null default false, gameweek_id uuid not null references public.gameweeks(id) on delete cascade, points_awarded integer not null default 0, result text check (result in ('exact','correct','wrong','void')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key (user_id, fixture_id));
create table public.daily_activity (user_id uuid not null references public.profiles(id) on delete cascade, activity_date date not null, logged_in boolean not null default false, predictions_count integer not null default 0, primary key (user_id, activity_date));
create table public.weekly_qualification (user_id uuid not null references public.profiles(id) on delete cascade, gameweek_id uuid not null references public.gameweeks(id) on delete cascade, active_days integer not null default 0, qualified boolean not null default false, computed_at timestamptz not null default now(), primary key (user_id, gameweek_id));
create table public.leagues (id uuid primary key default gen_random_uuid(), name text not null, owner_id uuid not null references public.profiles(id) on delete cascade, invite_code text not null unique, created_at timestamptz not null default now());
create table public.league_members (league_id uuid not null references public.leagues(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, joined_at timestamptz not null default now(), primary key (league_id, user_id));
create table public.wallet_ledger (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, amount_naira numeric(12,2) not null, type public.ledger_type not null, source_reference text not null, status public.ledger_status not null default 'pending', available_at timestamptz, note text, created_at timestamptz not null default now());
create table public.prize_awards (id uuid primary key default gen_random_uuid(), gameweek_id uuid not null references public.gameweeks(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, rank integer not null, amount_naira numeric(12,2) not null, unique(gameweek_id,user_id));
create table public.devices (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, fingerprint text not null, last_seen_at timestamptz not null default now(), unique(user_id,fingerprint));
create table public.fraud_flags (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, reason text not null, severity text not null default 'medium', resolved_at timestamptz, created_at timestamptz not null default now());
create table public.app_config (id boolean primary key default true, points jsonb not null default '{}'::jsonb, boosters jsonb not null default '{}'::jsonb, streak_days integer not null default 7, prize_tiers jsonb not null default '[]'::jsonb, minimum_predictions integer not null default 5, qualification_rules jsonb not null default '{}'::jsonb, withdrawal_rules jsonb not null default '{}'::jsonb, general_referral_rules jsonb not null default '{}'::jsonb, weekly_budget_naira numeric(12,2) not null default 0, prizes_paused boolean not null default false);
create table public.audit_log (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id) on delete set null, action text not null, entity text not null, entity_id text, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

insert into public.app_config (id, points, boosters, streak_days, prize_tiers, minimum_predictions, qualification_rules, withdrawal_rules, general_referral_rules, weekly_budget_naira, prizes_paused)
values (true, '{"exact":5,"correct":2,"wrong":0}'::jsonb, '{"enabled":true,"bonusPerStreak":1}'::jsonb, 7, '[]'::jsonb, 5, '{"minActiveDays":3,"minFixturesForDayToCount":3,"minPredictionsPerActiveDay":1}'::jsonb, '{}'::jsonb, '{}'::jsonb, 0, false)
on conflict (id) do nothing;

create or replace function public.is_admin() returns boolean language sql stable security invoker set search_path = public as $$ select exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin' and status = 'active'); $$;
create or replace function public.compute_weekly_qualification(p_user_id uuid, p_gameweek_id uuid) returns public.weekly_qualification language plpgsql security invoker set search_path = public as $$ declare result public.weekly_qualification; min_days int; min_preds int; min_fixtures int; begin select coalesce((qualification_rules->>'minActiveDays')::int,3), coalesce((qualification_rules->>'minPredictionsPerActiveDay')::int,1), coalesce((qualification_rules->>'minFixturesForDayToCount')::int,3) into min_days,min_preds,min_fixtures from public.app_config where id=true; select count(*)::int, (count(*) >= min_days) into result.active_days,result.qualified from public.daily_activity d join public.gameweeks g on g.id=p_gameweek_id where d.user_id=p_user_id and d.activity_date between (g.starts_at at time zone 'Africa/Lagos')::date and (g.ends_at at time zone 'Africa/Lagos')::date and d.logged_in and d.predictions_count >= min_preds and (select count(*) from public.fixtures f where (f.kickoff_at at time zone 'Africa/Lagos')::date=d.activity_date and f.status <> 'void') >= min_fixtures; result.user_id:=p_user_id; result.gameweek_id:=p_gameweek_id; result.computed_at:=now(); insert into public.weekly_qualification as q values (result.*) on conflict (user_id,gameweek_id) do update set active_days=excluded.active_days,qualified=excluded.qualified,computed_at=excluded.computed_at; return result; end; $$;
create or replace view public.weekly_leaderboard with (security_invoker=true) as select p.nickname, p.id as user_id, pr.gameweek_id, coalesce(sum(pr.points_awarded),0)::int points, count(*) filter (where pr.result='exact')::int exact_scores, count(*) filter (where pr.result='correct')::int correct_results, min(pr.created_at) first_prediction_at, coalesce(q.qualified,false) qualified from public.profiles p join public.predictions pr on pr.user_id=p.id left join public.weekly_qualification q on q.user_id=p.id and q.gameweek_id=pr.gameweek_id group by p.id,p.nickname,pr.gameweek_id,q.qualified;
create or replace view public.user_balances with (security_invoker=true) as select user_id, coalesce(sum(amount_naira) filter (where status='available'),0) available, coalesce(sum(amount_naira) filter (where status='pending'),0) pending, coalesce(sum(amount_naira) filter (where type='prize' and status<>'reversed'),0) prize_total, coalesce(sum(amount_naira) filter (where type like 'referral%' and status<>'reversed'),0) referral_total from public.wallet_ledger group by user_id;

create or replace function public.record_prediction_activity(p_user_id uuid, p_activity_date date) returns void language plpgsql security definer set search_path = public as $$ begin insert into public.daily_activity(user_id, activity_date, logged_in, predictions_count) values (p_user_id, p_activity_date, false, 1) on conflict (user_id, activity_date) do update set predictions_count = public.daily_activity.predictions_count + 1; end; $$;

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,nickname,email,referral_code,email_verified) values (new.id, coalesce(new.raw_user_meta_data->>'nickname', split_part(new.email,'@',1)), new.email, upper(substr(encode(gen_random_bytes(6),'hex'),1,8)), new.email_confirmed_at is not null) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

alter table public.profiles enable row level security; alter table public.competitions enable row level security; alter table public.teams enable row level security; alter table public.fixtures enable row level security; alter table public.gameweeks enable row level security; alter table public.predictions enable row level security; alter table public.daily_activity enable row level security; alter table public.weekly_qualification enable row level security; alter table public.leagues enable row level security; alter table public.league_members enable row level security; alter table public.wallet_ledger enable row level security; alter table public.prize_awards enable row level security; alter table public.devices enable row level security; alter table public.fraud_flags enable row level security; alter table public.app_config enable row level security; alter table public.audit_log enable row level security;
create policy profiles_self on public.profiles for select to authenticated using (id=(select auth.uid()) or public.is_admin()); create policy profiles_self_update on public.profiles for update to authenticated using (id=(select auth.uid()) or public.is_admin()) with check (id=(select auth.uid()) or public.is_admin());
create policy fixtures_read on public.fixtures for select to authenticated using (true); create policy teams_read on public.teams for select to authenticated using (true); create policy competitions_read on public.competitions for select to authenticated using (true); create policy gameweeks_read on public.gameweeks for select to authenticated using (true);
create policy predictions_self on public.predictions for select to authenticated using (user_id=(select auth.uid())); create policy activity_self on public.daily_activity for select to authenticated using (user_id=(select auth.uid())); create policy qualification_self on public.weekly_qualification for select to authenticated using (user_id=(select auth.uid())); create policy league_read on public.leagues for select to authenticated using (owner_id=(select auth.uid()) or exists(select 1 from public.league_members m where m.league_id=id and m.user_id=(select auth.uid()))); create policy membership_self on public.league_members for select to authenticated using (user_id=(select auth.uid())); create policy wallet_self on public.wallet_ledger for select to authenticated using (user_id=(select auth.uid())); create policy awards_self on public.prize_awards for select to authenticated using (user_id=(select auth.uid())); create policy devices_self on public.devices for select to authenticated using (user_id=(select auth.uid())); create policy fraud_self on public.fraud_flags for select to authenticated using (user_id=(select auth.uid())); create policy config_read on public.app_config for select to authenticated using (true); create policy audit_admin on public.audit_log for select to authenticated using (public.is_admin());
revoke insert,update,delete on public.wallet_ledger, public.prize_awards, public.fixtures, public.app_config, public.audit_log from anon, authenticated;
grant select on public.weekly_leaderboard, public.user_balances to authenticated;
